package com.jmadsen.dashhop;
import android.content.*;import android.os.*;import android.util.*;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
final class Diagnostics {
 static Context context;static String id="unavailable",session=UUID.randomUUID().toString();static File current,dir;static int part;static final Map<String,Object> state=new LinkedHashMap<>();
 static synchronized void init(Context c){if(context!=null)return;context=c.getApplicationContext();try{id=DiagnosticIdentity.get(context.getSharedPreferences("diagnostic_identity",0));}catch(Exception e){id=UUID.randomUUID().toString();state.put("identity_persisted",false);state.put("identity_scope_override","process only; persistent storage unavailable");}
 dir=new File(context.getFilesDir(),"diagnostics");dir.mkdirs();Thread.UncaughtExceptionHandler prior=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{error("uncaught",error);if(prior!=null)prior.uncaughtException(thread,error);});info("process_started");}
 static synchronized void status(String key,Object value){state.put(key,value);}
 static synchronized String header(){try{android.util.DisplayMetrics d=context.getResources().getDisplayMetrics();try{android.view.WindowManager window=context.getSystemService(android.view.WindowManager.class);if(window!=null){android.util.DisplayMetrics real=new android.util.DisplayMetrics();window.getDefaultDisplay().getRealMetrics(real);d=real;}}catch(Exception ignored){}Map<String,Object> profile=new LinkedHashMap<>();profile.put("manufacturer",Build.MANUFACTURER);profile.put("brand",Build.BRAND);profile.put("model",Build.MODEL);profile.put("device",Build.DEVICE);profile.put("product",Build.PRODUCT);profile.put("board",Build.BOARD);profile.put("hardware",Build.HARDWARE);profile.put("supported_abis",Arrays.asList(Build.SUPPORTED_ABIS));profile.put("total_ram_bytes","unknown");try{android.app.ActivityManager manager=context.getSystemService(android.app.ActivityManager.class);if(manager!=null){android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();manager.getMemoryInfo(memory);profile.put("total_ram_bytes",memory.totalMem);}}catch(Exception ignored){}profile.put("android_release",Build.VERSION.RELEASE);profile.put("api",Build.VERSION.SDK_INT);profile.put("build_id",Build.ID);profile.put("build_display",Build.DISPLAY);profile.put("security_patch",Build.VERSION.SECURITY_PATCH);profile.put("screen_width",d.widthPixels);profile.put("screen_height",d.heightPixels);profile.put("density",d.density);profile.put("mcu","unknown");profile.put("can_decoder","unknown");
 Map<String,Object> snapshot=new LinkedHashMap<>(state);ShortcutRepository r=new ShortcutRepository(context);snapshot.put("utility_hvac_enabled",r.flag(DockUtilities.HVAC,true));snapshot.put("utility_weather_enabled",r.flag(DockUtilities.WEATHER,true));snapshot.put("utility_clock_enabled",r.flag(DockUtilities.CLOCK,true));snapshot.put("utility_audio_enabled",r.flag(DockUtilities.AUDIO,true));snapshot.put("utility_notes_enabled",r.flag(DockUtilities.NOTES,true));snapshot.put("dock_edge",r.str("edge","bottom"));snapshot.put("handle_fraction",r.fraction(r.str("edge","bottom")));snapshot.put("dock_collapsed",r.flag("hidden",false));snapshot.put("auto_collapse",r.flag("autoCollapse",true));snapshot.put("auto_delay_seconds",r.num("autoDelay",3));snapshot.put("weather_source",r.str("weatherSource","direct"));snapshot.put("weather_location_configured",r.prefs.contains("weatherLat"));snapshot.put("product_mode","standalone_dock");snapshot.put("app_window_management","not used");snapshot.put("accessibility_required",false);snapshot.put("overlay_permission",android.provider.Settings.canDrawOverlays(context));snapshot.put("hvac_app",r.str("hvacApp",""));snapshot.put("hvac_quick_action","org.dashhop.intent.action.HVAC_QUICK_CONTROL");snapshot.put("restore_dock_on_boot",r.flag("restoreDockOnBoot",true));snapshot.put("parked_state","UNKNOWN");return DiagnosticEnvelope.header(id,session,Instant.now().toString(),ZoneId.systemDefault().getId(),profile,snapshot).toString();}catch(Exception e){return "{\"type\":\"dashhop_log_header\",\"device_id\":\""+id+"\",\"session_id\":\""+session+"\",\"metadata_error\":true}";}}
 static synchronized void operation(String event,Map<String,Object> fields){for(Map.Entry<String,Object> e:fields.entrySet())state.put(e.getKey(),e.getValue());write(event,new JSONObject(fields).toString());}
 static synchronized void info(String event){write(event,"");}
 static synchronized void error(String event,Throwable e){StringBuilder frames=new StringBuilder(e.getClass().getSimpleName());for(int i=0;i<Math.min(5,e.getStackTrace().length);i++)frames.append(" | ").append(e.getStackTrace()[i]);write(event,frames.toString());}
 static void write(String event,String detail){try{if(dir==null)return;if(current==null||current.length()>200000){current=new File(dir,"DashHopper_"+System.currentTimeMillis()+"_"+id+"_"+session.substring(0,8)+"_"+(part++)+".log");try(FileOutputStream out=new FileOutputStream(current)){out.write((header()+"\n").getBytes(StandardCharsets.UTF_8));}File[] files=dir.listFiles((f,n)->n.endsWith(".log"));if(files!=null){Arrays.sort(files,Comparator.comparing(File::getName));for(int i=0;i<files.length-5;i++)files[i].delete();}}
 JSONObject line=new JSONObject();line.put("timestamp",Instant.now().toString());line.put("device_id",id);line.put("session_id",session);line.put("event",event);if(!detail.isEmpty())line.put("detail",detail.length()>4096?detail.substring(0,4096):detail);try(FileOutputStream out=new FileOutputStream(current,true)){out.write((line.toString()+"\n").getBytes(StandardCharsets.UTF_8));}Log.i("DashHopper","device="+id+" session="+session.substring(0,8)+" "+event);
 }catch(Exception ignored){/* Logging must not crash the launcher. */}}
 static synchronized void export(OutputStream out)throws IOException{out.write((header()+"\n").getBytes(StandardCharsets.UTF_8));File[] files=dir.listFiles((f,n)->n.endsWith(".log"));if(files!=null){Arrays.sort(files,Comparator.comparing(File::getName));byte[] buffer=new byte[8192];for(File f:files)try(InputStream in=new FileInputStream(f)){int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}}out.flush();}
}
